// Normalize common display names to their registry key
const aliases: Record<string, string> = {
  "Node.js": "Node",
  "Spring Boot": "Spring",
  "Apache Ignite": "ApacheIgnite",
  "scikit-learn": "ScikitLearn",
  "Scikit-learn": "ScikitLearn",
  "Three.js": "Three",
  "BLE 4.2": "BLE",
};

export function getTechLogo(name: string): TechLogo {
  const key = aliases[name] ?? name;
  return techLogos[key] ?? {
    name,
    path: techLogosFallback.path,
  };
}

export function getTechColor(name: string): string {
  const key = aliases[name] ?? name;
  return techColors[key] ?? "#ffffff";
}
